import AppKit
import LyraReaderKit
import CoreGraphics
import Foundation
import PDFKit

extension ReaderChecks {
    /// Form detection, filling, the verified save, and the same values seen by three other
    /// viewers.
    ///
    /// The fixture is committed and generated by `scripts/make-fixtures.py`; its prefilled
    /// values were written by the generator (a writer that is not this reader). The other
    /// direction is exercised twice: a copy filled in the reader is read back with this engine,
    /// with PDFKit's widget model and renderer, and with Poppler's and Ghostscript's text
    /// extractors; a copy filled by **PDFKit itself** is opened with this reader and its values
    /// are asserted.
    @MainActor
    static func formChecks(root: URL) async throws {
        let fixture = root.appendingPathComponent("tests/fixtures/form-fields.pdf")
        let encrypted = root.appendingPathComponent("tests/fixtures/form-fields-encrypted.pdf")
        let scratch = FileManager.default.temporaryDirectory
            .appendingPathComponent("lyra-reader-forms-\(UUID())")
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: scratch) }

        // ── Detection on the committed fixture ───────────────────────────────────────
        let probe = try RustEngine()
        let loaded = try probe.openDocument(at: fixture)
        require(loaded.pageCount == 2, "the form fixture has two pages")
        let info = try await probe.formInfo()
        require(!info.encrypted, "the form fixture is not encrypted")
        require(info.pdfVersion == "1.7", "the PDF version is read from the header")
        require(info.pageCount == 2, "the form info reports the page count")
        require(info.fields.count == 8, "all eight form fields are detected")
        require(info.fields.map(\.kind) == [.text, .text, .checkBox, .radio, .comboBox,
                                            .listBox, .signature, .text],
                "the field kinds are text, text, check box, radio, combo, list, signature, text")
        require(info.fields.map(\.name) == ["fullName", "email", "agree", "color", "country",
                                            "interests", "signature", "notes"],
                "the fully-qualified names are read from /T")
        let fullName = info.fields[0]
        let email = info.fields[1]
        let agree = info.fields[2]
        let color = info.fields[3]
        let country = info.fields[4]
        let interests = info.fields[5]
        let signature = info.fields[6]
        let notes = info.fields[7]
        require(email.value == "prefilled@example.com",
                "a value written by another tool is read from /V")
        require(email.page == 0 && abs(email.xPt - 72) < 0.01
                    && abs(email.yPt - 218) < 0.01
                    && abs(email.widthPt - 228) < 0.01
                    && abs(email.heightPt - 26) < 0.01,
                "the widget /Rect is mapped into view space on its page")
        require(email.widgets.count == 1 && email.widgets[0].page == 0,
                "the widget is associated with page 0 through /Annots")
        require(notes.page == 1 && abs(notes.yPt - 82) < 0.01,
                "a page-two widget uses its own page's geometry")
        require(notes.multiline, "/Ff marks the notes field multiline")
        require(!agree.checked, "the check box starts off")
        require(color.options.map(\.label) == ["Red", "Green", "Blue"],
                "the radio group's /Opt labels are read")
        require(color.selected == [1], "the radio's /V and /AS select Green")
        require(country.options.map(\.label) == ["Canada", "Japan", "Germany"],
                "the combo's /Opt options are read")
        require(country.value == "Canada" && country.selected == [0],
                "the combo's prefilled value is read")
        require(interests.value == "Reading" && interests.selected == [0],
                "the list box's prefilled value is read")
        require(signature.kind == .signature && !signature.editable,
                "a signature is a distinct, non-editable field kind")
        require(fullName.value == nil, "an empty text field has no value")

        // ── The form tool and unsaved values ─────────────────────────────────────────
        let state = AppState(engine: try RustEngine())
        state.setViewportSize(CGSize(width: 900, height: 650))
        state.newTab(url: fixture)
        try await eventually("form fields load for the AppState", {
            state.formLoadCompleted && !state.formLoading
        })
        require(!state.formToolActive, "the reader opens in normal reading mode")
        require(state.annotationTool == .select, "the default canvas tool is selection")
        require(state.formInfo.fields.count == 8, "the shell sees every field")
        state.toggleFormTool()
        require(state.formToolActive, "the Fill & Sign tool activates")
        require(state.annotationTool == .select,
                "form mode keeps the canvas in selection mode for reading clicks")
        let stateFields = state.formInfo.fields
        let stateFullName = stateFields[0]
        let stateEmail = stateFields[1]
        let stateAgree = stateFields[2]
        let stateColor = stateFields[3]
        let stateCountry = stateFields[4]
        let stateInterests = stateFields[5]
        let stateNotes = stateFields[7]

        state.focusFormField(stateFullName.id)
        require(state.formFocusedFieldID == stateFullName.id, "clicking a text field focuses it")
        state.updateFormText(stateFullName.id, text: "Ada Lovelace")
        require(state.formCurrentText(stateFullName) == "Ada Lovelace",
                "typing updates the reader's value, not the file")
        state.focusNextFormField()
        require(state.formFocusedFieldID == stateEmail.id,
                "Tab moves to the next field in page/top/left reading order")
        state.focusNextFormField(backwards: true)
        require(state.formFocusedFieldID == stateFullName.id, "Shift-Tab moves back")
        state.blurFormField()
        require(state.formFocusedFieldID == nil, "Escape leaves the field without leaving the tool")
        require(state.formToolActive, "leaving the field keeps the form tool active")

        state.toggleFormCheckbox(stateAgree.id)
        state.selectFormRadioOption(stateColor.id, index: 2)
        state.selectFormChoice(stateCountry.id, index: 1)
        state.selectFormChoice(stateInterests.id, index: 1)
        state.updateFormText(stateNotes.id, text: "Written on page two.")
        require(state.formHasPendingChanges, "the edits are pending in the reader")
        require(state.formChangedFields.count == 6, "six fields differ from the file")
        require(state.formPendingSummary?.contains("the file on disk is unchanged") == true,
                "the banner says the file on disk is unchanged")
        require(state.formFilledCount == 7,
                "seven fields are filled on screen (five edited plus the two prefilled ones)")

        // Leaving the tool must restore reading, while the pending values stay.
        let zoomBefore = state.zoomFactor
        state.toggleFormTool()
        require(!state.formToolActive && state.formFocusedFieldID == nil,
                "leaving the form tool restores reading and drops keyboard focus")
        require(state.annotationTool == .select, "reading interaction is still in selection mode")
        require(state.zoomFactor == zoomBefore, "leaving the form tool did not move the viewport")
        require(state.formHasPendingChanges, "leaving the tool does not discard unsaved values")
        state.toggleFormTool()
        require(state.formToolActive, "the form tool can be re-entered with its values intact")
        require(state.cancelFormTool(), "Escape on the canvas leaves the form tool")
        require(!state.formToolActive, "the canvas is back in reading mode after Escape")

        // ── Save a copy and read it back with this engine ────────────────────────────
        let filled = scratch.appendingPathComponent("filled.pdf")
        let didSave = await state.saveFilledForm(to: filled)
        require(didSave, "an explicit save writes a filled copy")
        let sourceBytes = try Data(contentsOf: fixture)
        let savedBytes = try Data(contentsOf: filled)
        require(savedBytes.starts(with: sourceBytes),
                "the saved file begins with every byte of the original")
        require(savedBytes.count > sourceBytes.count, "the save appended an incremental revision")

        let reopened = try RustEngine()
        _ = try reopened.openDocument(at: filled)
        let after = try await reopened.formInfo()
        let value = { (name: String) in after.fields.first { $0.name == name }! }
        require(value("fullName").value == "Ada Lovelace", "the text value reads back")
        require(value("agree").checked, "the check box state reads back")
        require(value("color").selected == [2], "the radio selection reads back")
        require(value("country").value == "Japan" && value("country").selected == [1],
                "the combo selection reads back")
        require(value("interests").value == "Running" && value("interests").selected == [1],
                "the list selection reads back")
        require(value("notes").value == "Written on page two.", "the page-two text reads back")
        require(value("email").value == "prefilled@example.com",
                "a field the save did not touch keeps its value")
        require(after.fields.allSatisfy { $0.editable == value($0.name).editable },
                "the fields keep their editability")
        require(after.fields.count == 8, "the save neither adds nor removes fields")

        // ── The replace-original path keeps a verified backup and reopens ─────────────
        let replaceSource = scratch.appendingPathComponent("replace-form.pdf")
        try FileManager.default.copyItem(at: fixture, to: replaceSource)
        let replaceState = AppState(engine: try RustEngine())
        replaceState.setViewportSize(CGSize(width: 900, height: 650))
        replaceState.newTab(url: replaceSource)
        try await eventually("the replace fixture's form loads", {
            replaceState.formLoadCompleted && !replaceState.formLoading
        })
        replaceState.toggleFormTool()
        let replaceFullName = replaceState.formInfo.fields[0]
        replaceState.updateFormText(replaceFullName.id, text: "Replaced on disk")
        let replaced = await replaceState.replaceOriginalWithFilledForm()
        require(replaced, "Write Form Values to Original replaces the open file")
        try await eventually("the reopened document shows the replaced form value", {
            replaceState.formInfo.fields.first { $0.name == "fullName" }?.value
                == "Replaced on disk"
        })
        let backups = try FileManager.default.contentsOfDirectory(atPath: scratch.path)
            .filter { $0.contains(".lyra-reader-backup-") && $0.hasSuffix(".pdf") }
        require(!backups.isEmpty, "the replace wrote a backup beside the file")
        let sourceBytesAfterReplace = try Data(contentsOf: replaceSource)
        require(sourceBytesAfterReplace.count > sourceBytes.count,
                "the replaced file carries the incremental form revision")

        // A form filled by another application: PDFKit writes its own values, then this reader
        // opens the file. This is the direction the committed fixture cannot prove by itself.
        let pdfkitFilled = scratch.appendingPathComponent("pdfkit-filled.pdf")
        try fillCopyWithPDFKit(source: fixture, destination: pdfkitFilled)
        let otherWriterProbe = try RustEngine()
        _ = try otherWriterProbe.openDocument(at: pdfkitFilled)
        let otherWriter = try await otherWriterProbe.formInfo()
        let otherValue = { (name: String) in otherWriter.fields.first { $0.name == name }! }
        require(otherValue("fullName").value == "Filled by PDFKit",
                "this reader reads a text value written by PDFKit")
        require(otherValue("agree").checked,
                "this reader reads a check box written by PDFKit")
        require(otherValue("color").selected == [2],
                "this reader reads a radio choice written by PDFKit")
        require(otherValue("country").value == "Japan",
                "this reader reads a combo value written by PDFKit")
        require(otherValue("interests").value == "Running",
                "this reader reads a list value written by PDFKit")

        // ── PDFKit's own reading and rendering of the saved copy ─────────────────────
        let pdfkit = try pdfKitWidgets(url: filled)
        let textWidgets = pdfkit.filter { $0.subtype == "/Tx" }
        let buttonWidgets = pdfkit.filter { $0.subtype == "/Btn" }
        let choiceWidgets = pdfkit.filter { $0.subtype == "/Ch" }
        require(textWidgets.count == 3, "PDFKit sees three text widgets")
        require(textWidgets[0].value == "Ada Lovelace",
                "PDFKit reads the text value from the saved widget")
        require(textWidgets[1].value == "prefilled@example.com",
                "PDFKit reads the untouched prefilled value")
        require(buttonWidgets.first?.state == 1, "PDFKit sees the check box on")
        require(buttonWidgets.count == 4 && buttonWidgets[3].state == 1
                    && buttonWidgets[1].state == 0 && buttonWidgets[2].state == 0,
                "PDFKit sees exactly the Blue radio on")
        require(choiceWidgets.first?.value == "Japan", "PDFKit reads the combo value")
        require(choiceWidgets.last?.value == "Running", "PDFKit reads the list value")

        let scale: CGFloat = 2
        let fullNameRect = value("fullName").widgets[0]
        let textInk = try pdfKitPixels(
            url: filled,
            viewSpaceRect: CGRect(x: fullNameRect.xPt + 5, y: fullNameRect.yPt + 3,
                                  width: fullNameRect.widthPt - 10,
                                  height: fullNameRect.heightPt - 6),
            scale: scale,
            predicate: { red, green, blue in red < 90 && green < 90 && blue < 90 }
        )
        require(textInk > 60,
                "PDFKit's render has text ink inside the filled text field (\(textInk) px)")
        let comboRect = value("country").widgets[0]
        let comboInk = try pdfKitPixels(
            url: filled,
            viewSpaceRect: CGRect(x: comboRect.xPt + 5, y: comboRect.yPt + 3,
                                  width: comboRect.widthPt - 24,
                                  height: comboRect.heightPt - 6),
            scale: scale,
            predicate: { red, green, blue in red < 90 && green < 90 && blue < 90 }
        )
        require(comboInk > 30,
                "PDFKit's render has the chosen combo value (\(comboInk) px)")

        // The committed fixture is the "before" picture for the two button states.
        let agreeRect = value("agree").widgets[0]
        let checkboxOff = try pdfKitPixels(
            url: fixture,
            viewSpaceRect: CGRect(x: agreeRect.xPt + 2, y: agreeRect.yPt + 2,
                                  width: agreeRect.widthPt - 4, height: agreeRect.heightPt - 4),
            scale: scale,
            predicate: { red, green, blue in red < 90 && green < 90 && blue < 90 }
        )
        let checkboxOn = try pdfKitPixels(
            url: filled,
            viewSpaceRect: CGRect(x: agreeRect.xPt + 2, y: agreeRect.yPt + 2,
                                  width: agreeRect.widthPt - 4, height: agreeRect.heightPt - 4),
            scale: scale,
            predicate: { red, green, blue in red < 90 && green < 90 && blue < 90 }
        )
        require(checkboxOn > checkboxOff + 20,
                "PDFKit draws the check mark that was not there before "
                + "(\(checkboxOff) → \(checkboxOn) px)")

        // Poppler: its text extractor reads the appearance streams, so the values must be there
        // for a user who opens the copy in a Poppler-based viewer.
        if let pdftotext = findTool("pdftotext") {
            let text = try runTool(pdftotext, arguments: ["-layout", filled.path, "-"])
            require(text.contains("Ada Lovelace"),
                    "Poppler's pdftotext shows the filled text value")
            require(text.contains("Japan"), "Poppler's pdftotext shows the chosen combo item")
            require(text.contains("Running"), "Poppler's pdftotext shows the chosen list item")
            require(text.contains("Written on page two."),
                    "Poppler's pdftotext shows the page-two text value")
        } else {
            print("NOTE: pdftotext is not installed; Poppler's view of the form was NOT measured")
        }

        // Ghostscript: `txtwrite` reads the same appearance streams through its own interpreter.
        if let gs = findTool("gs") {
            let cache = scratch.appendingPathComponent("gs-cache")
            try FileManager.default.createDirectory(at: cache, withIntermediateDirectories: true)
            let text = try runTool(
                gs,
                arguments: ["-q", "-dBATCH", "-dNOPAUSE", "-sDEVICE=txtwrite",
                            "-sOutputFile=-", filled.path],
                environment: ["XDG_CACHE_HOME": cache.path, "HOME": scratch.path]
            )
            require(text.contains("Ada Lovelace"),
                    "Ghostscript's txtwrite shows the filled text value")
            require(text.contains("Japan"), "Ghostscript shows the chosen combo item")
            require(text.contains("Written on page two."),
                    "Ghostscript shows the page-two text value")
        } else {
            print("NOTE: gs is not installed; Ghostscript's view of the form was NOT measured")
        }

        // ── Document properties: read, edit, verified save, read back ───────────────
        let propertyProbe = try RustEngine()
        _ = try propertyProbe.openDocument(at: fixture)
        let documentInfo = try await propertyProbe.documentInfo()
        require(!documentInfo.isEncrypted, "the properties fixture is not encrypted")
        require(documentInfo.pageCount == 2, "the information view reads the page count")
        require(documentInfo.pdfVersion == "1.7", "the information view reads the PDF version")
        require(documentInfo.hasInfoDictionary, "the fixture has an /Info dictionary")
        require(documentInfo.title == "LyraReader Form Fixture", "the /Title entry is read")
        require(documentInfo.author == "Fixture Author", "the /Author entry is read")
        require(documentInfo.subject == "AcroForm fields for the reader's form tool",
                "the /Subject entry is read")
        require(documentInfo.keywords == "forms, fixture, lyrareader", "the /Keywords entry is read")

        let propertiesState = AppState(engine: try RustEngine())
        propertiesState.setViewportSize(CGSize(width: 900, height: 650))
        propertiesState.newTab(url: fixture)
        propertiesState.loadDocumentInfo()
        try await eventually("the information view loads its facts and /Info values", {
            propertiesState.documentInfo != nil && !propertiesState.documentInfoLoading
        })
        require(!propertiesState.documentPropertiesAreDirty,
                "the properties draft starts from the file")
        require(!propertiesState.canSaveDocumentProperties,
                "Save is disabled while nothing has changed")
        propertiesState.updateDocumentProperty(.title, text: "Edited & 100% Title")
        propertiesState.updateDocumentProperty(.author, text: "Ada Lovelace; Alan Turing")
        propertiesState.updateDocumentProperty(.subject, text: "A corrected subject")
        propertiesState.updateDocumentProperty(.keywords, text: "one, two")
        require(propertiesState.documentPropertiesAreDirty,
                "an edit marks the properties dirty")
        require(propertiesState.canSaveDocumentProperties,
                "Save is enabled for a dirty, unencrypted document")
        require(propertiesState.documentPropertiesRefusal == nil,
                "an unencrypted file has no refusal reason")
        let propertiesCopy = scratch.appendingPathComponent("properties.pdf")
        let didSaveProperties = await propertiesState.saveDocumentProperties(to: propertiesCopy)
        require(didSaveProperties, "Save writes the four /Info entries into a copy")
        let propertiesSourceBytes = try Data(contentsOf: fixture)
        let propertiesSavedBytes = try Data(contentsOf: propertiesCopy)
        require(propertiesSavedBytes.starts(with: propertiesSourceBytes),
                "the properties save begins with every byte of the original")

        let propertiesProbe = try RustEngine()
        _ = try propertiesProbe.openDocument(at: propertiesCopy)
        let savedInfo = try await propertiesProbe.documentInfo()
        require(savedInfo.title == "Edited & 100% Title", "the title reads back from /Info")
        require(savedInfo.author == "Ada Lovelace; Alan Turing", "the author reads back")
        require(savedInfo.subject == "A corrected subject", "the subject reads back")
        require(savedInfo.keywords == "one, two", "the keywords read back")
        require(savedInfo.pageCount == 2 && savedInfo.pdfVersion == "1.7"
                    && !savedInfo.isEncrypted,
                "the read-only facts still describe the saved file")
        let savedForm = try await propertiesProbe.formInfo()
        require(savedForm.fields.first { $0.name == "email" }?.value == "prefilled@example.com",
                "saving properties leaves the form values untouched")
        if let pdf = PDFDocument(url: propertiesCopy) {
            let title = pdf.documentAttributes?[PDFDocumentAttribute.titleAttribute] as? String
            require(title == "Edited & 100% Title",
                    "PDFKit reads the edited title from the saved file")
        } else {
            require(false, "PDFKit could not open the properties copy")
        }

        // The reader's metadata panel must prefer the values the save wrote, not a stale XMP
        // packet. `form-fields.pdf` had no packet: the save creates one, so the title now comes
        // from XMP with the same text as /Info.
        let propertiesMetadataState = AppState(engine: try RustEngine())
        propertiesMetadataState.setViewportSize(CGSize(width: 900, height: 650))
        propertiesMetadataState.newTab(url: propertiesCopy)
        try await eventually("the saved properties copy's metadata loads", {
            propertiesMetadataState.document?.url == propertiesCopy
                && !propertiesMetadataState.metadataLoading
                && propertiesMetadataState.metadata != nil
        })
        require(propertiesMetadataState.metadata?.title.first == "Edited & 100% Title",
                "the metadata panel shows the edited title after saving")
        require(propertiesMetadataState.metadata?.title.source == .xmp,
                "the edited title comes from the created XMP packet")
        require(propertiesMetadataState.metadata?.authors.values == ["Ada Lovelace", "Alan Turing"],
                "the metadata panel reads the created creator sequence")
        require(propertiesMetadataState.metadata?.authors.source == .xmp,
                "the created packet's authors are preferred over /Info")
        if let pdf = PDFDocument(url: propertiesCopy) {
            let author = pdf.documentAttributes?[PDFDocumentAttribute.authorAttribute] as? String
            print("lyra-reader-properties: PDFKit attributes (created packet): \(pdf.documentAttributes ?? [:])")
            require(author?.contains("Ada Lovelace") == true && author?.contains("Alan Turing") == true,
                    "PDFKit reads the created packet's author list")
        } else {
            require(false, "PDFKit could not open the properties copy after the metadata checks")
        }

        // A document that already has a packet: editing two properties must update both sources,
        // and the packet's other properties (venue, DOI, year) must survive and stay recognised.
        let embeddedSource = scratch.appendingPathComponent("metadata-embedded.pdf")
        try FileManager.default.copyItem(
            at: root.appendingPathComponent("tests/fixtures/metadata-embedded.pdf"),
            to: embeddedSource
        )
        let embeddedState = AppState(engine: try RustEngine())
        embeddedState.setViewportSize(CGSize(width: 900, height: 650))
        embeddedState.newTab(url: embeddedSource)
        embeddedState.loadDocumentInfo()
        try await eventually("the embedded-metadata document's properties load", {
            embeddedState.documentInfo != nil && !embeddedState.documentInfoLoading
        })
        embeddedState.updateDocumentProperty(.title, text: "Edited Embedded Title")
        embeddedState.updateDocumentProperty(.author, text: "Ada Lovelace; Alan Turing; Grace Hopper")
        embeddedState.updateDocumentProperty(.subject, text: "A corrected subject")
        embeddedState.updateDocumentProperty(.keywords, text: "one, two")
        let embeddedCopy = scratch.appendingPathComponent("metadata-embedded-edited.pdf")
        let didSaveEmbedded = await embeddedState.saveDocumentProperties(to: embeddedCopy)
        require(didSaveEmbedded, "saving properties on a packet document writes a copy")

        let embeddedProbe = try RustEngine()
        _ = try embeddedProbe.openDocument(at: embeddedCopy)
        let embeddedInfo = try await embeddedProbe.documentInfo()
        require(embeddedInfo.title == "Edited Embedded Title", "the edited title reads back from /Info")
        require(embeddedInfo.author == "Ada Lovelace; Alan Turing; Grace Hopper",
                "the edited author reads back from /Info")
        require(embeddedInfo.subject == "A corrected subject", "the edited subject reads back")
        require(embeddedInfo.keywords == "one, two", "the edited keywords read back")

        let embeddedMetadataState = AppState(engine: try RustEngine())
        embeddedMetadataState.setViewportSize(CGSize(width: 900, height: 650))
        embeddedMetadataState.newTab(url: embeddedCopy)
        try await eventually("the edited packet document's metadata loads", {
            embeddedMetadataState.document?.url == embeddedCopy
                && !embeddedMetadataState.metadataLoading
                && embeddedMetadataState.metadata != nil
        })
        require(embeddedMetadataState.metadata?.title.first == "Edited Embedded Title",
                "the metadata panel shows the edited XMP title, not the old one")
        require(embeddedMetadataState.metadata?.title.source == .xmp,
                "the edited title still reports XMP as its source")
        require(embeddedMetadataState.metadata?.authors.values
                    == ["Ada Lovelace", "Alan Turing", "Grace Hopper"],
                "the creator sequence round-trips three authors")
        require(embeddedMetadataState.metadata?.venue.first == "Journal of Embedded Testing",
                "an unedited XMP property (venue) survives the save")
        require(embeddedMetadataState.metadata?.doi.first == "10.1234/embedded.2024.001",
                "an unedited XMP property (DOI) survives the save")
        require(embeddedMetadataState.metadata?.year.first == "2024",
                "an unedited XMP property (year) survives the save")
        if let pdf = PDFDocument(url: embeddedCopy) {
            print("lyra-reader-properties: PDFKit attributes (edited packet): \(pdf.documentAttributes ?? [:])")
            let title = pdf.documentAttributes?[PDFDocumentAttribute.titleAttribute] as? String
            require(title == "Edited Embedded Title",
                    "PDFKit reads the edited title from the packet-backed document")
            let author = pdf.documentAttributes?[PDFDocumentAttribute.authorAttribute] as? String
            require(author?.contains("Ada Lovelace") == true
                        && author?.contains("Alan Turing") == true
                        && author?.contains("Grace Hopper") == true,
                    "PDFKit reads all three authors")
        } else {
            require(false, "PDFKit could not open the edited packet-backed document")
        }

        // The properties replace path: backup, write, reopen, and the new value in the file.
        let propertiesReplaceSource = scratch.appendingPathComponent("replace-properties.pdf")
        try FileManager.default.copyItem(at: fixture, to: propertiesReplaceSource)
        let replacePropertiesState = AppState(engine: try RustEngine())
        replacePropertiesState.setViewportSize(CGSize(width: 900, height: 650))
        replacePropertiesState.newTab(url: propertiesReplaceSource)
        replacePropertiesState.loadDocumentInfo()
        try await eventually("the replace fixture's properties load", {
            replacePropertiesState.documentInfo != nil
                && !replacePropertiesState.documentInfoLoading
        })
        replacePropertiesState.updateDocumentProperty(.title, text: "Replaced title")
        let replacedProperties = await replacePropertiesState.replaceOriginalWithProperties()
        require(replacedProperties, "Write to This File replaces the open document")
        try await eventually("the reopened document reads the replaced title", {
            replacePropertiesState.documentInfo?.title == "Replaced title"
        })
        let propertiesBackups = try FileManager.default.contentsOfDirectory(atPath: scratch.path)
            .filter { $0.contains(".lyra-reader-backup-") && $0.hasSuffix(".pdf") }
        require(propertiesBackups.count >= backups.count + 1,
                "the properties replace wrote another verified backup")
        try await eventually("the reopened metadata panel shows the replaced title from XMP", {
            replacePropertiesState.metadata?.title.first == "Replaced title"
                && replacePropertiesState.metadata?.title.source == .xmp
        })

        // ── Encrypted documents are refused ──────────────────────────────────────────
        let encryptedProbe = try RustEngine()
        _ = try encryptedProbe.openDocument(at: encrypted)
        let encryptedInfo = try await encryptedProbe.formInfo()
        require(encryptedInfo.encrypted, "the encrypted fixture is reported encrypted")
        require(encryptedInfo.refusal?.lowercased().contains("encrypted") == true,
                "the refusal says the PDF is encrypted")
        require(encryptedInfo.fields.allSatisfy { !$0.editable },
                "an encrypted file's fields are shown read-only")
        let encryptedState = AppState(engine: try RustEngine())
        encryptedState.setViewportSize(CGSize(width: 900, height: 650))
        encryptedState.newTab(url: encrypted)
        try await eventually("form info loads for the encrypted file", {
            encryptedState.formLoadCompleted && !encryptedState.formLoading
        })
        encryptedState.toggleFormTool()
        require(!encryptedState.formToolActive,
                "the form tool refuses an encrypted document")
        require(encryptedState.lastError?.lowercased().contains("encrypted") == true,
                "the reader says why the encrypted document cannot be filled")
        let encryptedDestination = scratch.appendingPathComponent("encrypted-filled.pdf")
        do {
            _ = try await encryptedProbe.saveFilledForm(
                to: encryptedDestination,
                values: [FormFieldValue(fieldID: encryptedInfo.fields.first?.id ?? "f1",
                                        text: "must not be written")]
            )
            require(false, "the encrypted form save was refused")
        } catch {
            require(error.localizedDescription.lowercased().contains("encrypted"),
                    "the refusal explains that the PDF is encrypted")
            require(!FileManager.default.fileExists(atPath: encryptedDestination.path),
                    "the refused encrypted save wrote no file")
        }

        let encryptedProperties = try await encryptedProbe.documentInfo()
        require(encryptedProperties.isEncrypted,
                "the information view reports the encrypted document")
        let encryptedPropertiesState = AppState(engine: try RustEngine())
        encryptedPropertiesState.setViewportSize(CGSize(width: 900, height: 650))
        encryptedPropertiesState.newTab(url: encrypted)
        encryptedPropertiesState.loadDocumentInfo()
        try await eventually("the encrypted document's facts load", {
            encryptedPropertiesState.documentInfo != nil
                && !encryptedPropertiesState.documentInfoLoading
        })
        require(encryptedPropertiesState.documentPropertiesRefusal?
                    .lowercased().contains("encrypted") == true,
                "the information view explains why an encrypted file cannot be saved")
        require(!encryptedPropertiesState.canSaveDocumentProperties,
                "saving properties is disabled for an encrypted file")
        let encryptedPropertiesDestination = scratch.appendingPathComponent("encrypted-properties.pdf")
        do {
            _ = try await encryptedProbe.saveDocumentProperties(
                to: encryptedPropertiesDestination,
                properties: DocumentProperties(title: "must not be written")
            )
            require(false, "the encrypted properties save was refused")
        } catch {
            require(error.localizedDescription.lowercased().contains("encrypted"),
                    "the properties refusal explains that the PDF is encrypted")
            require(!FileManager.default.fileExists(atPath: encryptedPropertiesDestination.path),
                    "the refused encrypted properties save wrote no file")
        }
    }

    // MARK: - PDFKit helpers

    /// The widget values PDFKit reads from the saved file, in page order.
    @MainActor
    private static func pdfKitWidgets(
        url: URL
    ) throws -> [(subtype: String, value: String?, state: Int)] {
        guard let document = PDFDocument(url: url) else {
            throw NSError(domain: "LyraReader", code: 6, userInfo: [
                NSLocalizedDescriptionKey: "PDFKit could not open the saved form",
            ])
        }
        var widgets: [(subtype: String, value: String?, state: Int)] = []
        for index in 0..<document.pageCount {
            guard let page = document.page(at: index) else { continue }
            for annotation in page.annotations {
                guard annotation.type == "Widget" else { continue }
                widgets.append((
                    subtype: annotation.widgetFieldType.rawValue,
                    value: annotation.widgetStringValue,
                    state: annotation.buttonWidgetState.rawValue
                ))
            }
        }
        return widgets
    }

    /// Fills a copy with PDFKit's own form model — a genuinely different writer — and writes it.
    @MainActor
    private static func fillCopyWithPDFKit(source: URL, destination: URL) throws {
        guard let document = PDFDocument(url: source), let page = document.page(at: 0) else {
            throw NSError(domain: "LyraReader", code: 7, userInfo: [
                NSLocalizedDescriptionKey: "PDFKit could not open the form fixture",
            ])
        }
        var radioIndex = 0
        for annotation in page.annotations {
            switch annotation.widgetFieldType.rawValue {
            case "/Tx":
                if (annotation.widgetStringValue ?? "").isEmpty {
                    annotation.widgetStringValue = "Filled by PDFKit"
                }
            case "/Ch":
                if annotation.widgetStringValue == "Canada" {
                    annotation.widgetStringValue = "Japan"
                } else if annotation.widgetStringValue == "Reading" {
                    annotation.widgetStringValue = "Running"
                }
            case "/Btn":
                let controlType = annotation.widgetControlType.rawValue
                if controlType == 2 {
                    annotation.buttonWidgetState = .onState
                } else if controlType == 1 {
                    annotation.buttonWidgetState = radioIndex == 2 ? .onState : .offState
                    radioIndex += 1
                }
            default:
                break
            }
        }
        guard document.write(to: destination) else {
            throw NSError(domain: "LyraReader", code: 8, userInfo: [
                NSLocalizedDescriptionKey: "PDFKit could not write the filled copy",
            ])
        }
    }

    // MARK: - Command-line viewers

    private static func findTool(_ name: String) -> String? {
        for directory in ["/opt/homebrew/bin", "/usr/local/bin", "/usr/bin", "/bin"] {
            let candidate = URL(fileURLWithPath: directory).appendingPathComponent(name)
            if FileManager.default.isExecutableFile(atPath: candidate.path) {
                return candidate.path
            }
        }
        return nil
    }

    private static func runTool(
        _ tool: String,
        arguments: [String],
        environment: [String: String]? = nil
    ) throws -> String {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: tool)
        process.arguments = arguments
        if let environment {
            process.environment = ProcessInfo.processInfo.environment.merging(environment) {
                _, new in new
            }
        }
        let output = Pipe()
        let errors = Pipe()
        process.standardOutput = output
        process.standardError = errors
        try process.run()
        process.waitUntilExit()
        let data = output.fileHandleForReading.readDataToEndOfFile()
        let errorData = errors.fileHandleForReading.readDataToEndOfFile()
        let text = String(decoding: data, as: UTF8.self)
            + String(decoding: errorData, as: UTF8.self)
        guard process.terminationStatus == 0 else {
            throw NSError(domain: "LyraReader", code: 9, userInfo: [
                NSLocalizedDescriptionKey:
                    "\(tool) failed (\(process.terminationStatus)): \(text)",
            ])
        }
        return text
    }
}
